using System; using System.Linq; using System.Diagnostics; using SomniumSpace.Worlds.SomniumEuroTruck.Ets;
static class P { static void Main(string[] a){ var fs = EtsFileSystem.Mount("E:/SteamLibrary/steamapps/common/Euro Truck Simulator 2 Demo", out _);
 var sw=Stopwatch.StartNew(); var c=new EtsTrafficCatalog(fs); Console.WriteLine("catalog "+sw.ElapsedMilliseconds+" ms: "+c.Vehicles.Count+" entries, "+c.VehicleCount+" vehicles, trailers "+c.Trailers.Count+", hash "+c.TableHash+", countries "+c.Countries.Count());
 foreach(var n in new[]{"uk","czech","poland","france","germany","netherlands","belgium"}) Console.WriteLine("  "+c.Describe(n));
 foreach(var t in EtsTrafficCatalog.TypeNames) Console.WriteLine("  type "+t+": "+c.Vehicles.Count(v=>v.Type>=0&&EtsTrafficCatalog.TypeNames[v.Type]==t));
 foreach(var ln in new[]{"traffic_lane.road.motorway","traffic_lane.road.local","traffic_lane.road.expressway"}){ var l=c.Lane(ln); Console.WriteLine("  "+ln+" density "+l.Density+": "+string.Join(", ", l.Spawns.Select(s=>s.Rule+"="+EtsTrafficCatalog.TypeNames[s.Type]+"["+string.Join(" ",s.Required)+"/!"+string.Join(" ",s.Excluded)+"] "+s.CountAt(c.Hour)))); }
 foreach(var cn in new[]{"uk","czech","germany"}){ var co=c.CountryNamed(cn); foreach(int cls in new[]{0,1,2}) Console.WriteLine("  "+cn+" class "+cls+": local "+(c.SpeedLimit(co,"local_road",false,cls)*3.6f).ToString("0.0")+" urban "+(c.SpeedLimit(co,"local_road",true,cls)*3.6f).ToString("0.0")+" exp "+(c.SpeedLimit(co,"expressway",false,cls)*3.6f).ToString("0.0")+" mw "+(c.SpeedLimit(co,"motorway",false,cls)*3.6f).ToString("0.0")); }
 sw.Restart(); c.Prepare("uk"); Console.WriteLine("prepare uk "+sw.ElapsedMilliseconds+" ms"); sw.Restart(); c.Prepare("czech"); Console.WriteLine("prepare czech "+sw.ElapsedMilliseconds+" ms");
 foreach(int t in c.Trailers){ var v=c.Vehicles[t]; Console.WriteLine("  trailer "+v.Unit+" len "+v.Length.ToString("0.0")+" kingpin "+v.KingpinZ.ToString("0.00")+" axle "+v.AxleZ.ToString("0.00")+" ratio "+v.OwnRatio+" tags "+string.Join(",",v.Tags)+" wheel "+v.RearWheel+" mass "+v.Mass+"+"+v.CargoMass); }
 var uk=c.CountryNamed("uk");
 for(int i=0;i<c.VehicleCount;i++){ var v=c.Vehicles[i]; if(uk.Ratios[i]>0 && v.Type!=0) Console.WriteLine("  uk "+EtsTrafficCatalog.TypeNames[v.Type]+" "+v.Unit+" r="+uk.Ratios[i]+" len "+v.Length.ToString("0.0")+" hitch "+v.HitchZ.ToString("0.00")+" semi "+v.Semi+"/"+string.Join(",",v.TrailerTags)+" kw "+v.PowerKw+" max "+v.MaxSpeedKmh+(v.Semi?" trailer "+c.Vehicles[c.TrailerFor(i,7)].Unit+" back "+c.BackOf(i,c.TrailerFor(i,7)).ToString("0.0"):"")); }
} }
